import unittest
from candidate import below_zero

class TestBelowZero(unittest.TestCase):
    def test_normal_case_no_negative_balance(self):
        self.assertFalse(below_zero([1, 2, 3]))

    def test_normal_case_with_negative_operation(self):
        self.assertTrue(below_zero([1, 2, -4, 5]))

    def test_single_withdrawal(self):
        self.assertTrue(below_zero([-1]))

    def test_single_deposit(self):
        self.assertFalse(below_zero([1]))

    def test_multiple_operations_ending_positive(self):
        self.assertFalse(below_zero([10, -5, 2]))

    def test_multiple_operations_ending_negative(self):
        self.assertTrue(below_zero([10, -15]))

    def test_empty_list(self):
        self.assertFalse(below_zero([]))

    def test_all_positive_operations(self):
        self.assertFalse(below_zero([1, 2, 3, 4]))

    def test_all_negative_operations(self):
        self.assertTrue(below_zero([-1, -2, -3]))

    def test_operations_negative_at_first_step(self):
        self.assertTrue(below_zero([-2, 1]))

    def test_operations_negative_at_last_step(self):
        self.assertFalse(below_zero([1, 2, -3]))

    def test_operations_negative_at_middle_step(self):
        self.assertTrue(below_zero([1, -2, 3]))

    def test_operations_with_zero(self):
        self.assertFalse(below_zero([1, 0, -1]))

    def test_operations_with_float_values(self):
        self.assertTrue(below_zero([1.5, -2.5, 1]))

    def test_operations_with_mixed_floats(self):
        self.assertFalse(below_zero([1.5, 2.5, -4]))

    def test_operations_with_large_numbers(self):
        self.assertTrue(below_zero([1000000, -1000001]))

    def test_operations_with_negative_large_numbers(self):
        self.assertFalse(below_zero([-1000000, 1000001]))

    def test_operations_with_negative_minus_positive(self):
        self.assertTrue(below_zero([-5, 1, -4]))

    def test_operations_with_positive_minus_negative(self):
        self.assertFalse(below_zero([5, -1, -4]))

    def test_none_input(self):
        with self.assertRaises(TypeError):
            below_zero(None)

    def test_non_list_input(self):
        with self.assertRaises(TypeError):
            below_zero("not a list")

    def test_non_iterable_input(self):
        with self.assertRaises(TypeError):
            below_zero(123)

    def test_list_with_non_integer_elements(self):
        with self.assertRaises(TypeError):
            below_zero([1, "2", 3])
